// CSD_RATIONALE_BEGIN
// Built on attempt 2 (40.8% accuracy, 81.6% syntax) with two targeted fixes:
//
// Fix 1 — EOS rescue inside open spans (targeting `final_span_unclosed`, 10 cases):
//   In attempt 2, when `SafeRepetitionPenaltyStep` returns EOS inside a constrained
//   span, the loop breaks immediately leaving the span unclosed. We now call
//   `RollbackConstrainedToComplete` to find the last complete parse in the span buffer,
//   then `CloseConstrainedSpan` to emit `>>` (costs 1 extra step). If no complete
//   prefix exists in the buffer, we break unchanged — identical to attempt 2 behaviour
//   in that case. This directly targets the `<< total * frac >` (one `>` instead of
//   `>>`) class of failures where the buffer has a complete expression but EOS fires.
//
// Fix 2 — Guided prohibition of assignments and conditionals inside spans:
//   Explicit prohibition of `=` and `if`/`else` inside `<< >>` to discourage
//   `<<n2 =` and `<< expr if cond else expr >>` patterns. The parser already blocks
//   `=`, but guidance directs the model's intent before it reaches the parser.
//
// All other parameters are identical to attempt 2:
//   — closeReserve=80 budget-guard trigger
//   — SafeRepetitionPenaltyStep penalty 4.0
//   — Final cleanup via CloseSpanWithinBudget after loop exit
//   — Free unconstrained generation with RenderedEndsWith("<<") detection
//
// Attempt 9's regression (–12pp) was caused entirely by adding dead-end detection
// (with 50-step escapeBudget per span, ran far more steps than needed and disrupted
// the constrained budget). We do NOT add dead-end detection here.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (budget-guard branch, remaining <= closeReserve):
//     CloseSpanWithinBudget postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`.
//     Both the closed path (ci=false, vacuous) and the still-open path
//     (parser.IsValidPrefix(cc)) preserve the invariant. ✓
//
//   (!insideConstrainedOut branch):
//     RenderedEndsWith detection sets currentConstrainedOut := [], satisfying
//     IsValidPrefix([]) by method precondition. Otherwise insideConstrainedOut stays false
//     (vacuous). ✓
//
//   (IsCompletePrefix branch):
//     CloseConstrainedSpan sets insideConstrainedOut := false (vacuously true). ✓
//
//   (EOS-rescue path in constrained branch):
//     RollbackConstrainedToComplete postcondition: `parser.IsValidPrefix(rc)`. We set
//     currentConstrainedOut := rc (valid). CloseConstrainedSpan requires IsCompletePrefix(rc)
//     which we check before calling, and sets insideConstrainedOut := false (vacuous). ✓
//
//   (normal constrained step, non-EOS):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (final cleanup):
//     Same CloseSpanWithinBudget postcondition argument as budget-guard branch. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (budget-guard, steps_before = steps entering branch):
//     CloseSpanWithinBudget(remaining) postcondition: |cg| <= |generated| + remaining.
//     remaining = maxSteps - steps_before, so |cg| <= |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (!insideConstrainedOut): steps += 1; at most 1 token appended. ✓
//   (IsCompletePrefix): steps += 1; CloseConstrainedSpan appends at most one ">>" token. ✓
//
//   (EOS-rescue path, steps_eos = steps after EOS-step increment):
//     generated is unchanged until rollback. RollbackConstrainedToComplete removes tokens:
//     |rg| <= |generated|_before_rollback <= |generatedPrefix| + steps_eos - 1.
//     CloseConstrainedSpan: |cg| <= |rg| + 1 <= |generatedPrefix| + steps_eos.
//     After steps := steps_eos + 1 = steps_eos + 1:
//     |generated| = |cg| <= |generatedPrefix| + steps_eos = |generatedPrefix| + steps - 1 <= |generatedPrefix| + steps. ✓
//     steps <= maxSteps because steps < maxSteps was checked before the close. ✓
//
//   (normal constrained step, non-EOS): steps += 1; AppendConstrainedToken appends 1 token. ✓
//   (final cleanup): Same as budget-guard argument. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> write ONLY a single arithmetic expression. " +
  "Do NOT write variable assignments (no = sign inside << >>). " +
  "Do NOT write conditional expressions (no if/else inside << >>). " +
  "Use only: numbers, problem variables, +, -, *, /, //, %, **, (), int(). " +
  "Use int() when the result must be a whole number. " +
  "Use // for integer (floor) division. " +
  "Use the exact variable names from the problem statement. " +
  "Do not substitute numeric values for variables.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget guard: force-close with all remaining steps using dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Constrained step with repetition penalty to break !-loop dead ends
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // EOS inside open span: try rollback to last complete prefix and close before break
      if steps < maxSteps {
        var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
        if parser.IsCompletePrefix(rc) {
          generated := rg;
          currentConstrainedOut := rc;
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

